/** Called by the shared codegen entry point so help and its reference cannot drift. */
import { readFileSync, writeFileSync } from "node:fs";
import { COMMAND_LIST } from "../src/commands/index.js";
import { renderCommandHelp } from "../src/help.js";
import { PUBLIC_CONTRACT } from "../src/generated/contract.js";

const output = new URL("../REFERENCE.md", import.meta.url);
const skillSource = new URL("../../skills/storerouter/SKILL.md", import.meta.url);
const skillOutput = new URL("../src/generated/skill.ts", import.meta.url);
const text = [
  "<!-- Generated by npm run codegen. Do not edit. -->",
  "# CLI command reference",
  "",
  `Public API version: ${PUBLIC_CONTRACT.version}. Snapshot SHA-256: \`${PUBLIC_CONTRACT.sha256}\`.`,
  "",
  "Syntax and workflow notes come from the command registry. Request types, choices, defaults, bounds and descriptions come from the public contract.",
  "",
  ...COMMAND_LIST.flatMap((command) => [
    `## ${command.name}`,
    "",
    "```text",
    renderCommandHelp(command),
    "```",
    "",
  ]),
].join("\n");
// `storerouter skill` prints these, bundled so the guidance matches the build.
const skillModule = [
  "/** Generated by npm run codegen from skills/storerouter/SKILL.md and cli/REFERENCE.md. Do not edit. */",
  "export const SKILL_FILES: Readonly<Record<string, string>> = {",
  `  "SKILL.md": ${JSON.stringify(readFileSync(skillSource, "utf8"))},`,
  `  "references/commands.md": ${JSON.stringify(text)},`,
  "};",
  "",
].join("\n");
if (process.argv.includes("--check")) {
  if (readFileSync(output, "utf8") !== text)
    throw new Error("CLI reference is stale. Run npm run codegen.");
  if (readFileSync(skillOutput, "utf8") !== skillModule)
    throw new Error("Bundled CLI skill is stale. Run npm run codegen.");
} else {
  writeFileSync(output, text);
  writeFileSync(skillOutput, skillModule);
}
